// ===== EDIT THESE FOR YOUR LAN =====
const PMS_BASE = 'http://192.168.1.116:8010'; // PMS PC Ethernet IP
const DEVICE_NAME = 'Press Machine 1';        // must match machines.name in PMS
const DEVICE_UUID = '7dcfa25e-250c-4447-9b3a-0dfce0a639ad'; // optional: machines.plc_topic
const MACHINE_ID = null; // set to a number (e.g. 7) to force machine match; else null
// ====================================

msg.pmsBase = String(PMS_BASE).replace(/\/$/, '');
msg.deviceName = DEVICE_NAME;
msg.deviceUuid = DEVICE_UUID;
if (MACHINE_ID !== null && MACHINE_ID !== undefined) msg.machineId = MACHINE_ID;

// ===== store-and-forward spool =====
// EDIT to move the CSV. Use an ABSOLUTE path: a bare filename resolves against
// whatever working directory Node-RED was started in, which on an appliance
// install may not be writable.
//   Linux / Ubuntu : '/var/tmp/servo_press_spool.csv'
//   Windows        : 'C:/eap-pms/servo_press_spool.csv'
// The directory is created automatically if it does not exist.
//
// If this path is not visible from a host shell, Node-RED is writing inside its
// own filesystem namespace (Kubernetes pod, Docker, snap, or PrivateTmp).
// 'report spool location' prints the path and hostname it really used.
//
// RUNNING IN A POD: a container filesystem is wiped when the pod restarts, so
// '/var/tmp' buffers fine but loses the backlog on a restart. Put the CSV on the
// mounted volume that holds the Node-RED user directory instead - '/data' in the
// official image. Run the 'probe writable paths' inject to see which directories
// this container can actually write to.
const SPOOL_FILE = '/var/tmp/servo_press_spool.csv';

// CSV column -> Node-RED reading name. Must match the readings built downstream.
const SPOOL_COLUMNS = [
    ['status', 'status:Int16'],
    ['live_position', 'Live position'],
    ['live_force', 'Live force'],
    ['live_velocity', 'Live Velocity'],
    ['live_mode', 'Live Mode'],
    ['total_steps', 'Total Steps'],
    ['live_step', 'Live Step'],
    ['recipe_number', 'Recipe number'],
    ['total_amount', 'Total amount'],
    ['pass_amount', 'Pass amount'],
    ['ng_amount', 'NG amount'],
    ['standby_time', 'Standby time'],
    ['pressing_time', 'Pressing time'],
    ['production_time', 'Production time'],
    ['alarm_code', 'Alarm Code'],
    ['pressing_result', 'Pressing result'],
    ['pressed_position_step1', 'Pressed position (Step 1)'],
    ['pressed_position_step2', 'Pressed position (Step 2)']
];

msg.spoolFile = SPOOL_FILE;
flow.set('spoolFile', SPOOL_FILE);
flow.set('spoolColumns', SPOOL_COLUMNS);
flow.set('spoolHeader', 'iso_time,origin,device_name,device_uuid,' + SPOOL_COLUMNS.map(c => c[0]).join(','));
flow.set('pmsBase', msg.pmsBase);

return msg;

// Raw Modbus integers (PMS applies scale: pos×0.001, force×0.1, time×0.01/0.1)
const origin = Date.now();
const ctx = context.flow;

let tick = ctx.get('tick') || 0;
let total = ctx.get('total') || 1200;
let pass = ctx.get('pass') || 1184;
let ng = ctx.get('ng') || 16;
let faultSeq = ctx.get('faultSeq') || 0;
let warnSeq = ctx.get('warnSeq') || 0;
let goodSeq = ctx.get('goodSeq') || 0;
tick += 1;

// Alarm code tables (manufacturer alarm table 9.1 style).
// FAULT_CODES fail the part (Pressing result = NG); WARN_CODES raise while the part stays OK.
// Rotating through them gives the Alarms tab one bar per code instead of a single 101 bar.
const FAULT_CODES = [101, 102, 103, 104];
const WARN_CODES = [201, 202, 305];

// Cycle: Idle(0) → Pressing(3) → Result OK(5) → Idle...
const phase = tick % 6;
let status = 0;
let liveStep = 0;
let pressingResult = 0;
let alarm = 0;
let pos = 10000;   // 10.000 mm
let force = 0;     // 0.0 kgf
let vel = 0;       // 0.000 mm/s

if (phase === 0 || phase === 1) {
    status = 0;
    liveStep = 0;
    pos = 10000 + (tick % 50);
    force = 20 + (tick % 10);
    vel = 100 + (tick % 20);
} else if (phase === 2 || phase === 3) {
    status = 3; // pressing
    liveStep = phase === 2 ? 1 : 2;
    pos = 35000 + phase * 4000 + (tick % 200);
    force = 800 + (tick % 150);
    vel = 1200 + (tick % 100);
} else {
    status = 5; // result ready (4–8)
    liveStep = 2;
    pos = 42600 + (tick % 80);
    force = 950 + (tick % 40);
    vel = 50 + (tick % 10);
    pressingResult = (tick % 5 === 0) ? 2 : 1; // occasional NG
    if (pressingResult === 2) {
        ng += 1;
        alarm = FAULT_CODES[faultSeq % FAULT_CODES.length];
        faultSeq += 1;
    } else {
        pass += 1;
        goodSeq += 1;
        // Warning-class alarm on every 3rd good result: code raises, part is still OK.
        if (goodSeq % 3 === 0) {
            alarm = WARN_CODES[warnSeq % WARN_CODES.length];
            warnSeq += 1;
        } else {
            alarm = 0;
        }
    }
    total = pass + ng;
}

ctx.set('tick', tick);
ctx.set('total', total);
ctx.set('pass', pass);
ctx.set('ng', ng);
ctx.set('faultSeq', faultSeq);
ctx.set('warnSeq', warnSeq);
ctx.set('goodSeq', goodSeq);

function R(name, value) {
    return { name: name, value: String(value), origin: origin };
}

const readings = [
    R('device type:String', 'Press'),
    R('status:Int16', status),
    R('Live position', pos),
    R('Live force', force),
    R('Live Velocity', vel),
    R('Status*1', status),
    R('Live Mode', 1),
    R('Total Steps', 2),
    R('Live Step', liveStep),
    R('Recipe number', 3),
    R('Total amount', total),
    R('Pass amount', pass),
    R('NG amount', ng),
    R('Standby time', 15),      // ×0.1 → 1.5 s
    R('Pressing time', 22),     // ×0.1 → 2.2 s
    R('Production time', 280),  // ×0.01 → 2.80 s
    R('Alarm Code', alarm),
    R('Pressing result', pressingResult),
    R('Pressed position (Step 1)', 38000),
    R('Pressed position (Step 2)', 42600)
];

// Clear result fields while pressing (status 3) — matches Modbus rule
if (status === 3) {
    for (const name of [
        'Total amount', 'Pass amount', 'NG amount',
        'Standby time', 'Pressing time', 'Production time',
        'Alarm Code', 'Pressing result',
        'Pressed position (Step 1)', 'Pressed position (Step 2)'
    ]) {
        const i = readings.findIndex(r => r.name === name);
        if (i >= 0) readings[i].value = '0';
    }
}

const body = {
    id: 'sim-' + origin,
    syncBy: 'MODBUS',
    deviceName: msg.deviceName,
    device: msg.deviceUuid,
    origin: origin,
    readings: readings
};
if (msg.machineId) body.machine_id = msg.machineId;

msg.payload = body;
// Kept for the spool: msg.payload is overwritten by the HTTP response
msg.telemetry = body;
msg.headers = { 'Content-Type': 'application/json' };
msg.url = msg.pmsBase + '/api/machines/telemetry';
msg.method = 'POST';
msg.tick = tick;
msg.status = status;
return msg;

// Delivered, or does the sample need to go to the CSV spool?
// A connection failure leaves msg.statusCode as a string ('ECONNREFUSED'),
// so only a numeric 2xx counts as accepted by PMS.
const code = msg.statusCode;
const ok = typeof code === 'number' && code >= 200 && code < 300;
msg.ok = ok;

// Replayed rows are handled by 'drain result', not spooled again here
if (msg.replay) return [null, null, msg];

if (ok) {
    node.status({ fill: 'green', shape: 'dot', text: 'online' });
    return [msg, null, null];
}
node.status({ fill: 'yellow', shape: 'ring', text: 'offline -> CSV spool' });
return [null, msg, null];

// Offline: append this sample to the CSV spool for later replay
const columns = flow.get('spoolColumns') || [];
const body = msg.telemetry || {};
const readings = body.readings || [];

const byName = {};
for (const r of readings) byName[r.name] = r.value;

function cell(value) {
    const s = (value === undefined || value === null) ? '' : String(value);
    return /[",\r\n]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s;
}

const origin = body.origin || Date.now();
const row = [
    new Date(Number(origin)).toISOString(),
    origin,
    body.deviceName || '',
    body.device || ''
].concat(columns.map(c => byName[c[1]])).map(cell).join(',');

const count = (flow.get('spoolCount') || 0) + 1;
flow.set('spoolCount', count);

let payload = row;
if (!flow.get('spoolHeaderWritten')) {
    // First row this session: write the header so the CSV opens cleanly.
    // Replay skips any header line, so an extra one is harmless.
    flow.set('spoolHeaderWritten', true);
    payload = (flow.get('spoolHeader') || '') + '\n' + row;
}

msg.filename = msg.spoolFile || flow.get('spoolFile') || 'servo_press_spool.csv';
msg.payload = payload;
node.status({ fill: 'yellow', shape: 'dot', text: count + ' row(s) spooled' });
return msg;

// PMS answered, so try to push whatever the outage collected
if (flow.get('draining')) return null;
if (!flow.get('spoolColumns')) return null; // cfg node has not run yet

const count = flow.get('spoolCount') || 0;
if (!count && !msg.force) return null;

flow.set('draining', true);
node.status({ fill: 'blue', shape: 'ring', text: 'reading spool' });
return { filename: flow.get('spoolFile') || 'servo_press_spool.csv' };

// Oldest row first, so PMS replays history in the order it happened
const text = String(msg.payload || '');
const lines = text.split(/\r?\n/)
    .map(l => l.trim())
    .filter(l => l && l.indexOf('iso_time') !== 0);

flow.set('spoolLines', lines);
flow.set('spoolCount', lines.length);
node.status({ text: lines.length + ' row(s) to resend' });
return {};

// Send one spooled row; 'drain result' loops back here until the CSV is empty
const columns = flow.get('spoolColumns') || [];
const lines = flow.get('spoolLines') || [];
const file = flow.get('spoolFile') || 'servo_press_spool.csv';
const header = flow.get('spoolHeader') || '';

if (!lines.length) {
    flow.set('spoolCount', 0);
    flow.set('draining', false);
    flow.set('spoolHeaderWritten', true);
    node.status({ fill: 'green', shape: 'dot', text: 'spool empty' });
    return [null, { filename: file, payload: header }];
}

const line = lines.shift();
flow.set('spoolLines', lines);
flow.set('spoolCount', lines.length);

function parseRow(text) {
    const out = [];
    let cur = '';
    let quoted = false;
    for (let i = 0; i < text.length; i++) {
        const ch = text[i];
        if (quoted) {
            if (ch === '"') {
                if (text[i + 1] === '"') { cur += '"'; i++; } else { quoted = false; }
            } else { cur += ch; }
        } else if (ch === '"') {
            quoted = true;
        } else if (ch === ',') {
            out.push(cur); cur = '';
        } else {
            cur += ch;
        }
    }
    out.push(cur);
    return out;
}

const cells = parseRow(line);
const origin = Number(cells[1]) || Date.parse(cells[0]) || Date.now();
const values = cells.slice(4);

const readings = [{ name: 'device type:String', value: 'Press', origin: origin }];
const statusIdx = columns.findIndex(c => c[0] === 'status');
const status = statusIdx >= 0 ? values[statusIdx] : '0';
readings.push({ name: 'status:Int16', value: String(status), origin: origin });
readings.push({ name: 'Status*1', value: String(status), origin: origin });
columns.forEach((c, i) => {
    if (c[0] === 'status') return; // already sent as status:Int16 + Status*1
    const v = values[i];
    if (v === undefined || v === '') return;
    readings.push({ name: c[1], value: String(v), origin: origin });
});

const body = {
    id: 'spool-' + origin,
    syncBy: 'MODBUS',
    deviceName: cells[2],
    device: cells[3],
    origin: origin,
    readings: readings
};

const out = {
    payload: body,
    telemetry: body,
    headers: { 'Content-Type': 'application/json' },
    url: (flow.get('pmsBase') || '') + '/api/machines/telemetry',
    method: 'POST',
    replay: true,
    spoolLine: line
};
node.status({ text: 'resending, ' + lines.length + ' left' });
return [out, null];

// Result of a replayed row
if (msg.ok) return [{ next: true }, null]; // keep draining

// PMS dropped again: put the row back and keep the CSV for the next reconnect
const lines = flow.get('spoolLines') || [];
if (msg.spoolLine) lines.unshift(msg.spoolLine);
flow.set('spoolLines', []);
flow.set('spoolCount', lines.length);
flow.set('draining', false);
flow.set('spoolHeaderWritten', true);
node.status({ fill: 'yellow', shape: 'ring', text: 'offline again, ' + lines.length + ' row(s) held' });

const header = flow.get('spoolHeader') || '';
return [null, {
    filename: flow.get('spoolFile') || 'servo_press_spool.csv',
    payload: [header].concat(lines).join('\n')
}];

// No spool file yet (nothing was ever buffered) - nothing to replay
flow.set('draining', false);
node.status({ text: 'no spool file' });
return null;

// One-shot proof of where the spool CSV actually lives.
// Node-RED may run in a container, a snap, or a systemd unit with PrivateTmp=yes,
// in which case '/var/tmp' here is NOT the '/var/tmp' a host shell sees.
if (flow.get('spoolProved')) return null;
flow.set('spoolProved', true);
msg.filename = flow.get('spoolFile');
return msg;

// Read-back succeeded, so the file exists. Report the path plus enough
// environment to tell whether that path is inside Node-RED's own namespace.
const path = msg.filename || flow.get('spoolFile');
const text = String(msg.payload || '');
const rows = text.split(/\r?\n/).filter(l => l.trim() && l.indexOf('iso_time') !== 0).length;

const host = env.get('HOSTNAME') || env.get('COMPUTERNAME') || '?';
const where = [
    'HOSTNAME=' + host,
    'USER=' + (env.get('USER') || env.get('USERNAME') || '?'),
    'HOME=' + (env.get('HOME') || env.get('USERPROFILE') || '?'),
    'NODE_RED_HOME=' + (env.get('NODE_RED_HOME') || '?'),
    'PWD=' + (env.get('PWD') || '?'),
    'container=' + (env.get('container') || 'not set')
].join('   ');

node.warn('SPOOL FILE OK -> ' + path + '   (' + text.length + ' bytes, ' + rows + ' buffered row(s))');
node.warn('Node-RED is running as: ' + where);
node.warn('If that hostname is not your shell hostname, the path above is inside Node-RED\'s own ' +
    'filesystem (container / pod / snap / PrivateTmp). A host "ls" will never show it: copy it out with ' +
    'kubectl cp, or reach GET /servo-press-spool.csv through a port-forward.');

// Emit it as a message too, so a debug node wired here shows the same facts
return {
    topic: 'spool location',
    payload: {
        spoolFile: path,
        bytes: text.length,
        bufferedRows: rows,
        hostname: host,
        user: env.get('USER') || env.get('USERNAME') || '?',
        home: env.get('HOME') || env.get('USERPROFILE') || '?',
        nodeRedHome: env.get('NODE_RED_HOME') || '?',
        kubernetesPod: !!(env.get('KUBERNETES_SERVICE_HOST') || env.get('KUBERNETES_PORT')),
        container: env.get('container') || 'not set'
    }
};

// Serve the spool CSV over HTTP so it can be collected without filesystem access
msg.filename = flow.get('spoolFile') || '/var/tmp/servo_press_spool.csv';
return msg;

// Hand the CSV back as a file download
msg.headers = {
    'Content-Type': 'text/csv; charset=utf-8',
    'Content-Disposition': 'attachment; filename="servo_press_spool.csv"'
};
msg.statusCode = 200;
msg.payload = String(msg.payload || '');
return msg;

// A spool read failed. For an HTTP request answer it; otherwise just say so.
const path = flow.get('spoolFile') || '?';
const reason = (msg.error && msg.error.message) ? msg.error.message : 'unknown error';
if (msg.res) {
    msg.statusCode = 404;
    msg.headers = { 'Content-Type': 'text/plain; charset=utf-8' };
    msg.payload = 'No spool file at ' + path + '\n' + reason +
        '\nNothing is buffered, which is normal while PMS is reachable.\n';
    return msg;
}
node.warn('Could not read the spool file at ' + path + ': ' + reason);
return null;

// Which directories can Node-RED actually write to in this container?
// A pod's own filesystem is wiped on restart, so the spool belongs on a mounted
// volume - usually the Node-RED user directory. Each probe writes a tiny file with
// createDir OFF, so only directories that already exist can succeed.
const home = env.get('HOME') || env.get('USERPROFILE') || '';
const nrHome = env.get('NODE_RED_HOME') || '';
const candidates = [
    '/data',
    home ? home + '/.node-red' : '',
    home,
    nrHome,
    '/var/lib/node-red',
    '/var/tmp',
    '/tmp'
];

const seen = {};
const out = [];
for (const dir of candidates) {
    if (!dir || seen[dir]) continue;
    seen[dir] = true;
    out.push({
        probeDir: dir,
        filename: dir.replace(/\/+$/, '') + '/.pms_spool_probe',
        payload: 'pms spool probe ' + new Date().toISOString()
    });
}

node.status({ text: 'probing ' + out.length + ' path(s)' });
node.warn('Probing ' + out.length + ' candidate spool directories. ' +
    'A WRITABLE path can hold the CSV; whether it SURVIVES a pod restart depends on it being a mounted volume.');
return [out];

// The write succeeded, so this directory exists and is writable
node.warn('WRITABLE  ' + msg.probeDir + '   -> usable as SPOOL_FILE, e.g. ' +
    msg.probeDir.replace(/\/+$/, '') + '/servo_press_spool.csv');
return null;

// The write failed: directory missing, or read-only in this container
const reason = (msg.error && msg.error.message) ? msg.error.message : 'unknown error';
node.warn('NOT usable ' + (msg.probeDir || '?') + '   -> ' + reason);
return null;

// Read the spool for viewing in the editor. msg.topic picks what happens next.
msg.filename = flow.get('spoolFile') || '/var/tmp/servo_press_spool.csv';
msg.view = (msg.topic === 'page') ? 'page' : 'summary';
if (msg.topic === 'rewind') {
    flow.set('viewCursor', 0);
    msg.view = 'summary';
}
return msg;

// Show the buffered CSV without leaving the editor.
// Output 1: one summary message. Output 2: one message per row, a page at a time.
// One row per message on purpose - the debug sidebar truncates messages at
// 1000 characters by default, so a page packed into a single message would be cut off.
const PAGE = 5;
const file = msg.filename;
const text = String(msg.payload || '');
const lines = text.split(/\r?\n/).map(l => l.trim()).filter(Boolean);
const header = (lines.length && lines[0].indexOf('iso_time') === 0)
    ? lines[0]
    : (flow.get('spoolHeader') || '');
const names = header.split(',');
const rows = lines.filter(l => l.indexOf('iso_time') !== 0);

function parseRow(text) {
    const out = [];
    let cur = '';
    let quoted = false;
    for (let i = 0; i < text.length; i++) {
        const ch = text[i];
        if (quoted) {
            if (ch === '"') {
                if (text[i + 1] === '"') { cur += '"'; i++; } else { quoted = false; }
            } else { cur += ch; }
        } else if (ch === '"') {
            quoted = true;
        } else if (ch === ',') {
            out.push(cur); cur = '';
        } else {
            cur += ch;
        }
    }
    out.push(cur);
    return out;
}

if (msg.view === 'summary') {
    const first = rows.length ? parseRow(rows[0]) : [];
    const last = rows.length ? parseRow(rows[rows.length - 1]) : [];
    const cursor = flow.get('viewCursor') || 0;
    node.status({ text: rows.length + ' row(s) buffered' });
    return [{
        topic: 'spool summary',
        payload: {
            spoolFile: file,
            bytes: text.length,
            bufferedRows: rows.length,
            columns: names.length,
            oldestSample: first[0] || null,
            newestSample: last[0] || null,
            nextPageStartsAtRow: Math.min(cursor + 1, rows.length || 1)
        }
    }, null];
}

if (!rows.length) {
    node.status({ text: 'spool empty' });
    return [{ topic: 'spool summary', payload: { spoolFile: file, bufferedRows: 0 } }, null];
}

let cursor = flow.get('viewCursor') || 0;
if (cursor >= rows.length) cursor = 0; // wrap round to the start
const end = Math.min(cursor + PAGE, rows.length);

const out = [];
for (let i = cursor; i < end; i++) {
    const cells = parseRow(rows[i]);
    const obj = {};
    names.forEach((n, j) => { obj[n] = cells[j]; });
    out.push({ topic: 'spool row ' + (i + 1) + ' / ' + rows.length, payload: obj });
}

flow.set('viewCursor', end);
node.status({ text: 'rows ' + (cursor + 1) + '-' + end + ' of ' + rows.length });
return [null, out];

// Query this Node-RED's own admin API from inside the container
msg.method = 'GET';
msg.url = 'http://127.0.0.1:1880/settings';
msg.payload = '';
return msg;

// Node-RED's own /settings says where http-in endpoints are mounted, so the
// download URL can be reported instead of guessed.
const s = msg.payload;
const root = (s && typeof s === 'object' && s.httpNodeRoot) ? s.httpNodeRoot : null;

if (!root) {
    node.warn('Could not read Node-RED /settings (status ' + msg.statusCode + '). The download path ' +
        'is httpNodeRoot + "/servo-press-spool.csv"; httpNodeRoot is defined in settings.js and ' +
        'defaults to "/".');
    return null;
}

const p = (root === '/' ? '' : String(root).replace(/\/+$/, '')) + '/servo-press-spool.csv';
node.warn('CSV download path: ' + p + '   (Node-RED ' + (s.version || '?') +
    ', httpNodeRoot "' + root + '")');
node.warn('Open it on the same host and port you reach the editor on: http://<editor-host>' + p +
    '   - inside the container it is http://127.0.0.1:1880' + p);
return {
    topic: 'spool download path',
    payload: { httpNodeRoot: root, downloadPath: p, nodeRedVersion: s.version || null }
};
